reference_solution:
def permuteUnique(nums):
    nums = sorted(nums)
    res, cur = [], []
    used = [False] * len(nums)
    def bt():
        if len(cur) == len(nums):
            res.append(cur[:])
            return
        for i in range(len(nums)):
            if used[i]:
                continue
            if i > 0 and nums[i] == nums[i - 1] and not used[i - 1]:
                continue
            used[i] = True
            cur.append(nums[i])
            bt()
            cur.pop()
            used[i] = False
    bt()
    return res

